package com.profa.document;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/documents")public class DocumentController{final TeacherDocumentRepository r;public DocumentController(TeacherDocumentRepository r){this.r=r;}@GetMapping("/mine")@PreAuthorize("hasRole('TEACHER')")public List<TeacherDocument> mine(Authentication a){UUID id=UUID.fromString(a.getName());return r.findAll().stream().filter(x->id.equals(x.getTeacherId())).toList();}@PostMapping@PreAuthorize("hasRole('TEACHER')")public TeacherDocument add(Authentication a,@RequestBody TeacherDocument x){x.setTeacherId(UUID.fromString(a.getName()));return r.save(x);}}